//! The JS-facing runtime state: transient buffers and drained last
//! errors, stored in the process-wide [`Registry`] under crate-owned
//! tags and exposed to JavaScript through the exports generated by
//! [`bffi_runtime_abi`](super::bffi_runtime_abi).
//!
//! # Transient buffers (tags `0x0401`)
//!
//! Returned `String`/byte-buffer values cannot cross `bun:ffi` as
//! values (no cstring returns, no structs by value). Instead, the Rust
//! side stores a [`CopiedBuf`] and hands out an opaque [`Handle`]; the
//! JS side reads the bytes through the `bffi_buffer` /
//! `bffi_buffer_length` pointer pair and releases the slot with
//! `bffi_types_free`.
//!
//! # Last-error transport (tag `0x0400`)
//!
//! After observing a non-OK [`ErrorCode`], the JS side calls
//! `bffi_error_take_last`; this drains the thread-local last error,
//! converts it into a [`JsErrorShape`] and stores it. Name and message
//! are then read through the `bffi_error_*` exports and released with
//! `bffi_error_free`. The source's `Display` string (when there is a
//! source) is materialized into the entry and surfaces as the JS
//! `Error.cause` through `bffi_error_cause_ptr` / `bffi_error_cause_len`.
//!
//! # Pointer lifetime
//!
//! Pointers handed out by `buffer_ptr` / `error_message_ptr` /
//! `error_cause_ptr` are valid until the owning handle is released
//! (or the process ends). JavaScript must read the bytes synchronously
//! and then call the matching free export; holding the pointer across
//! releases is undefined behavior on the JS side (the generational
//! scheme makes the stale handle detectable, but the raw pointer is
//! NOT revalidated).

// Internal module aliases (the pre-merge crate names).
use crate::bffi_core;
use crate::bffi_error;
use crate::bffi_types;
use std::error::Error as _;
use std::sync::{Arc, OnceLock};

use bffi_core::{Handle, Registry, TypeTag};
use bffi_error::{JsErrorExt, JsErrorName, JsErrorShape};
use bffi_types::CopiedBuf;

use super::error::BuildError;

/// The type tag of the drained-error table.
const ERROR_TAG: TypeTag = TypeTag(0x0400);

/// The type tag of the transient-buffer table.
const BUFFER_TAG: TypeTag = TypeTag(0x0401);

/// A drained last error, stored so the JS side can read name,
/// message, and cause through the generated exports.
struct ErrorEntry {
    shape: JsErrorShape,
    /// The source's `Display` string, materialized at `take_error`
    /// time (the boxed source itself is never stored).
    cause: Option<String>,
    /// The user-defined status of a `#[derive(BffiError)]` error
    /// (`0` when the error carries none).
    user_code: u32,
    /// The derived variant name (empty for framework errors).
    variant: String,
    /// The pre-encoded payload record (empty = no payload).
    payload: Vec<u8>,
    /// The captured Rust backtrace (present only when
    /// `RUST_BACKTRACE` was active at error creation).
    backtrace: Option<String>,
}

/// Declares both runtime tables in the global registry, exactly once
/// per process.
///
/// The memoized `Result` inside the [`OnceLock`] makes the outcome
/// sticky: every later caller gets the same result as the first
/// initializer, whether `Ok` or `Err`. The tags are crate-owned, so a
/// `TagAlreadyRegistered` means two initializers raced (or a user
/// module squatted the tag); both map to [`BuildError::TagInUse`].
///
/// If one declare succeeds and the other fails, that partial state is
/// permanent: the registry has no undeclare, and the memoized `Err`
/// stops all later retries.
fn tables() -> Result<(), BuildError> {
    static TABLES: OnceLock<Result<(), BuildError>> = OnceLock::new();
    *TABLES.get_or_init(|| {
        Registry::global()
            .declare::<ErrorEntry>(ERROR_TAG)
            .map_err(|_| BuildError::TagInUse(ERROR_TAG))?;
        Registry::global()
            .declare::<CopiedBuf>(BUFFER_TAG)
            .map_err(|_| BuildError::TagInUse(BUFFER_TAG))?;
        Ok(())
    })
}

/// Stores `bytes` in the transient-buffer table and returns its fresh,
/// opaque [`Handle`].
///
/// The bytes are owned by the table (the [`CopiedBuf`] keeps its own
/// copy); JavaScript reads them through `bffi_buffer` /
/// `bffi_buffer_length` and releases the slot with `bffi_types_free`.
///
/// # Errors
///
/// [`BuildError::TableFull`] when the buffer table has no free slot, or
/// [`BuildError::TagInUse`] if table initialization ever failed earlier
/// in the process (the memoized outcome).
pub fn store_bytes(bytes: CopiedBuf) -> Result<Handle, BuildError> {
    tables()?;
    store_bytes_inner(bytes)
}

/// The post-declare store path. `NotRegistered` is unreachable after a
/// successful declare (the registry has no undeclare), so every
/// remaining error is grouped into [`BuildError::TableFull`]
/// (`RegistryError` is `#[non_exhaustive]`; same defensive wildcard as
/// the other crates).
fn store_bytes_inner(bytes: CopiedBuf) -> Result<Handle, BuildError> {
    Registry::global()
        .insert(BUFFER_TAG, Arc::new(bytes))
        .map_err(|_| BuildError::TableFull(BUFFER_TAG))
}

/// Returns the pointer to the bytes behind `handle`, or a null pointer
/// for null/stale/foreign handles.
///
/// The pointer stays valid until the handle is released with
/// `bffi_types_free` (or the process ends). See the module docs for the
/// JS-side lifetime contract.
#[must_use]
pub fn buffer_ptr(handle: Handle) -> *const u8 {
    match Registry::global().get_typed::<CopiedBuf>(handle) {
        Some(bytes) => bytes.as_slice().as_ptr(),
        None => std::ptr::null(),
    }
}

/// Returns the length in bytes behind `handle`, or `0` for
/// null/stale/foreign handles.
#[must_use]
pub fn buffer_len(handle: Handle) -> u64 {
    match Registry::global().get_typed::<CopiedBuf>(handle) {
        Some(bytes) => bytes.as_slice().len() as u64,
        None => 0,
    }
}

/// Releases the buffer slot behind `handle`; `true` if a live slot was
/// removed. Arc holders keep the bytes alive; the handle goes stale
/// immediately.
#[must_use]
pub fn free_buffer(handle: Handle) -> bool {
    Registry::global()
        .remove_typed::<CopiedBuf>(handle)
        .is_some()
}

/// Drains the thread-local [last error](bffi_core), converts it into a
/// [`JsErrorShape`] and stores it for the JS side.
///
/// Returns the fresh handle, or [`Handle::NULL`] when no error is
/// stored, the tables could not be initialized, or the error table is
/// full. In the full-table case the detail is lost - the JS side still
/// observes the non-OK status code, only the message is gone (the
/// table holds up to 2^24 slots, so this is a theoretical path).
#[must_use]
pub fn take_error() -> Handle {
    if tables().is_err() {
        return Handle::NULL;
    }
    let Some(error) = bffi_core::take_last_error() else {
        return Handle::NULL;
    };
    // The cause must be materialized before the shape consumes
    // `error`: only the source's `Display` string is kept, never the
    // box itself.
    let cause = error.source().map(std::string::ToString::to_string);
    let shape = error.to_js_shape();
    // The B3 rich fields move out of the (boxed) rich slot.
    let (user_code, variant, payload, backtrace) = match error.rich {
        Some(rich) => (
            rich.user_code.unwrap_or(0),
            rich.variant.unwrap_or_default(),
            rich.payload.unwrap_or_default(),
            rich.backtrace,
        ),
        None => (0, String::new(), Vec::new(), None),
    };
    match Registry::global().insert(
        ERROR_TAG,
        Arc::new(ErrorEntry {
            shape,
            cause,
            user_code,
            variant,
            payload,
            backtrace,
        }),
    ) {
        Ok(handle) => handle,
        Err(_) => Handle::NULL,
    }
}

/// Returns the JS constructor name of the drained error behind
/// `handle`, or `None` for null/stale/foreign handles.
#[must_use]
pub fn error_name(handle: Handle) -> Option<JsErrorName> {
    Registry::global()
        .get_typed::<ErrorEntry>(handle)
        .map(|entry| entry.shape.name)
}

/// Returns the pointer to the UTF-8 message bytes of the drained error
/// behind `handle`, or a null pointer for invalid handles.
///
/// The pointer stays valid until the handle is released with
/// `bffi_error_free`. See the module docs for the JS-side lifetime
/// contract.
#[must_use]
pub fn error_message_ptr(handle: Handle) -> *const u8 {
    match Registry::global().get_typed::<ErrorEntry>(handle) {
        Some(entry) => entry.shape.message.as_ptr(),
        None => std::ptr::null(),
    }
}

/// Returns the length in bytes of the drained error message behind
/// `handle`, or `0` for invalid handles.
#[must_use]
pub fn error_message_len(handle: Handle) -> u64 {
    match Registry::global().get_typed::<ErrorEntry>(handle) {
        Some(entry) => entry.shape.message.len() as u64,
        None => 0,
    }
}

/// Returns the pointer to the UTF-8 cause bytes (the source's
/// `Display` string) of the drained error behind `handle`, or a null
/// pointer when the error has no source or the handle is invalid.
///
/// The pointer stays valid until the handle is released with
/// `bffi_error_free`. See the module docs for the JS-side lifetime
/// contract.
#[must_use]
pub fn error_cause_ptr(handle: Handle) -> *const u8 {
    match Registry::global().get_typed::<ErrorEntry>(handle) {
        Some(entry) => entry
            .cause
            .as_ref()
            .map_or(std::ptr::null(), |cause| cause.as_ptr()),
        None => std::ptr::null(),
    }
}

/// Returns the length in bytes of the drained error cause behind
/// `handle`, or `0` when the error has no source or the handle is
/// invalid.
#[must_use]
pub fn error_cause_len(handle: Handle) -> u64 {
    match Registry::global().get_typed::<ErrorEntry>(handle) {
        Some(entry) => entry.cause.as_ref().map_or(0, |cause| cause.len() as u64),
        None => 0,
    }
}

/// Releases the drained-error slot behind `handle`; `true` if a live
/// slot was removed.
#[must_use]
pub fn free_error(handle: Handle) -> bool {
    Registry::global()
        .remove_typed::<ErrorEntry>(handle)
        .is_some()
}

/// Returns the user-defined status of the drained error behind
/// `handle` (`0` for framework errors without a user code).
#[must_use]
pub fn error_user_code(handle: Handle) -> u32 {
    Registry::global()
        .get_typed::<ErrorEntry>(handle)
        .map_or(0, |entry| entry.user_code)
}

/// Returns the pointer to the derived variant name bytes of the
/// drained error behind `handle`, or a null pointer when absent or
/// the handle is invalid. Valid until `bffi_error_free`.
#[must_use]
pub fn error_variant_ptr(handle: Handle) -> *const u8 {
    match Registry::global().get_typed::<ErrorEntry>(handle) {
        Some(entry) if !entry.variant.is_empty() => entry.variant.as_ptr(),
        _ => std::ptr::null(),
    }
}

/// Returns the byte length of the derived variant name of the drained
/// error behind `handle` (`0` = absent).
#[must_use]
pub fn error_variant_len(handle: Handle) -> u64 {
    Registry::global()
        .get_typed::<ErrorEntry>(handle)
        .map_or(0, |entry| entry.variant.len() as u64)
}

/// Returns the derived variant name of the drained error behind
/// `handle` (empty for framework errors), or `None` for invalid
/// handles.
#[must_use]
pub fn error_variant(handle: Handle) -> Option<String> {
    Registry::global()
        .get_typed::<ErrorEntry>(handle)
        .map(|entry| entry.variant.clone())
}

/// Returns the pointer to the pre-encoded payload record of the
/// drained error behind `handle`, or a null pointer when there is no
/// payload or the handle is invalid. The record is the last element
/// of the error storage and stays valid until `bffi_error_free`.
#[must_use]
pub fn error_payload_ptr(handle: Handle) -> *const u8 {
    match Registry::global().get_typed::<ErrorEntry>(handle) {
        Some(entry) if !entry.payload.is_empty() => entry.payload.as_ptr(),
        _ => std::ptr::null(),
    }
}

/// Returns the payload record length of the drained error behind
/// `handle` (`0` = no payload), or `0` for invalid handles.
#[must_use]
pub fn error_payload_len(handle: Handle) -> u64 {
    Registry::global()
        .get_typed::<ErrorEntry>(handle)
        .map_or(0, |entry| entry.payload.len() as u64)
}

/// Returns the pointer to the captured Rust backtrace of the drained
/// error behind `handle`, or a null pointer when no backtrace was
/// captured (`RUST_BACKTRACE` inactive) or the handle is invalid.
#[must_use]
pub fn error_stack_ptr(handle: Handle) -> *const u8 {
    match Registry::global().get_typed::<ErrorEntry>(handle) {
        Some(entry) => entry
            .backtrace
            .as_ref()
            .map_or(std::ptr::null(), |trace| trace.as_ptr()),
        None => std::ptr::null(),
    }
}

/// Returns the backtrace length of the drained error behind `handle`
/// (`0` = no backtrace), or `0` for invalid handles.
#[must_use]
pub fn error_stack_len(handle: Handle) -> u64 {
    Registry::global()
        .get_typed::<ErrorEntry>(handle)
        .map_or(0, |entry| {
            entry
                .backtrace
                .as_ref()
                .map_or(0, |trace| trace.len() as u64)
        })
}

#[cfg(test)]
mod tests {
    use super::*;
    use bffi_core::{BffiError, ErrorCode};

    #[test]
    fn buffer_roundtrip_stores_and_peeks_bytes() {
        let handle =
            store_bytes(CopiedBuf::from_slice(b"payload")).expect("buffer table must have room");
        assert!(!buffer_ptr(handle).is_null());
        assert_eq!(buffer_len(handle), 7);
        // SAFETY: `buffer_ptr` handed out the pointer to exactly
        // `buffer_len(handle)` owned bytes and the handle is still live.
        let bytes =
            unsafe { std::slice::from_raw_parts(buffer_ptr(handle), buffer_len(handle) as usize) };
        assert_eq!(bytes, b"payload");
        assert!(free_buffer(handle), "first free must remove the slot");
    }

    #[test]
    fn buffer_access_after_free_reports_nothing() {
        let handle = store_bytes(CopiedBuf::from_vec(vec![1, 2, 3])).expect("room");
        assert!(free_buffer(handle));
        assert!(!free_buffer(handle), "second free must be a no-op");
        assert!(buffer_ptr(handle).is_null(), "stale handle -> null ptr");
        assert_eq!(buffer_len(handle), 0, "stale handle -> zero length");
    }

    #[test]
    fn null_and_foreign_handles_are_rejected() {
        assert!(buffer_ptr(Handle::NULL).is_null());
        assert_eq!(buffer_len(Handle::NULL), 0);
        assert!(!free_buffer(Handle::NULL));
        assert!(error_message_ptr(Handle::NULL).is_null());
        assert_eq!(error_message_len(Handle::NULL), 0);
        assert!(error_cause_ptr(Handle::NULL).is_null());
        assert_eq!(error_cause_len(Handle::NULL), 0);
        assert!(!free_error(Handle::NULL));
        assert_eq!(error_name(Handle::NULL), None);

        // A live buffer under a foreign-tag handle: the tag barrier
        // must reject it on both tables.
        let buffer = store_bytes(CopiedBuf::from_slice(b"x")).expect("room");
        let foreign = Handle::new(TypeTag(0x8FFF), buffer.generation(), buffer.index());
        assert!(buffer_ptr(foreign).is_null());
        assert!(error_message_ptr(foreign).is_null());
        assert!(error_cause_ptr(foreign).is_null());
        assert!(free_buffer(buffer));
    }

    #[test]
    fn take_error_drains_the_thread_local_slot_into_a_handle() {
        assert!(
            take_error().is_null(),
            "test threads must start with a clean slot"
        );

        bffi_core::set_last_error(BffiError::new(ErrorCode::InvalidUtf8, "bad bytes"));
        let handle = take_error();
        assert!(!handle.is_null(), "a stored error must produce a handle");
        assert_eq!(error_name(handle), Some(JsErrorName::TypeError));
        assert_eq!(error_message_len(handle), 9);
        // SAFETY: `error_message_ptr` handed out the pointer to exactly
        // `error_message_len(handle)` owned UTF-8 bytes and the handle
        // is still live.
        let bytes = unsafe {
            std::slice::from_raw_parts(
                error_message_ptr(handle),
                error_message_len(handle) as usize,
            )
        };
        assert_eq!(bytes, b"bad bytes");

        // The slot was drained: a second take sees nothing.
        assert!(take_error().is_null());
        assert!(free_error(handle));
        assert!(!free_error(handle), "second free must be a no-op");
    }

    #[test]
    fn take_error_rejects_stale_handles_like_the_table_contract() {
        let handle = take_error_after_store();
        assert!(free_error(handle));
        assert_eq!(error_name(handle), None, "stale handle -> no name");
    }

    /// The test-double source whose `Display` mirrors the example
    /// crate's `MathError` ("division by 0" for a zero divisor).
    #[derive(Debug)]
    struct MathError {
        divisor: u32,
    }

    impl std::fmt::Display for MathError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "division by {}", self.divisor)
        }
    }

    impl std::error::Error for MathError {}

    #[test]
    fn take_error_materializes_the_source_display_as_cause() {
        bffi_core::set_last_error(BffiError::with_source(
            ErrorCode::DomainError,
            "checked_div failed",
            MathError { divisor: 0 },
        ));
        let handle = take_error();
        assert!(!handle.is_null());
        assert_eq!(error_cause_len(handle), 13);
        // SAFETY: `error_cause_ptr` handed out the pointer to exactly
        // `error_cause_len(handle)` owned UTF-8 bytes and the handle
        // is still live until `free_error`.
        let cause = unsafe {
            std::slice::from_raw_parts(error_cause_ptr(handle), error_cause_len(handle) as usize)
        };
        assert_eq!(cause, b"division by 0");
        assert!(free_error(handle));
        assert!(
            error_cause_ptr(handle).is_null(),
            "freed handle -> null cause ptr"
        );
        assert_eq!(error_cause_len(handle), 0);
    }

    #[test]
    fn take_error_reports_no_cause_without_a_source() {
        // A caught panic (release shim path) stores no source.
        bffi_core::set_last_error(BffiError::new(ErrorCode::Panic, "boom"));
        let handle = take_error();
        assert!(!handle.is_null());
        assert!(
            error_cause_ptr(handle).is_null(),
            "no source -> null cause ptr"
        );
        assert_eq!(error_cause_len(handle), 0);
        assert!(free_error(handle));
    }

    fn take_error_after_store() -> Handle {
        bffi_core::set_last_error(BffiError::new(ErrorCode::Error, "boom"));
        let handle = take_error();
        assert!(!handle.is_null());
        handle
    }

    #[test]
    fn concurrent_store_and_free_never_resurrect() {
        std::thread::scope(|scope| {
            for worker in 0..4 {
                scope.spawn(move || {
                    for step in 0..64 {
                        let payload = vec![worker, step as u8, 7];
                        let handle = store_bytes(CopiedBuf::from_vec(payload)).expect("room");
                        assert_eq!(buffer_len(handle), 3);
                        assert!(free_buffer(handle));
                        assert!(buffer_ptr(handle).is_null());
                    }
                });
            }
        });
    }
}
